 target.regenDelay=.55;this.burst(target.model.group.position,target.enemy?'#ffad65':'#b8e5f0',heavy?18:10);this.events.float?.(target,amount,target.enemy?'enemy':'player');this.shake=heavy?.21:.09;this.beep(heavy?60:130,heavy?.21:.12,.1,'sawtooth');
